use xiom.io;
use xiom.string;
fn title_case(text: Str) -> Str {
  return string.str_upper(text);
}

fn add_exclamation(text: Str) -> Str {
  return text + "!!!";
}

fn repeat_word(word: Str, times: Int) -> Str {
  var result = "";
  var count = 0;
  while count < times {
    result = string.str_concat(result, word);
    count = count + 1;
  }
}
fn main() {
  let message = "hello world";
  let step1 = title_case(message);
  let step2 = add_exclamation(step1);
  io.println("Text formatting complete!");
  let chant = repeat_word("XIOM! ", 4);
  io.println("Chant generated!");
}
